def normalize_phone(s: str) -> str:
    import re
    match = re.fullmatch(r'\d{3}-\d{3}-\d{4}', s)
    if match:
        return f'({match.group(1)}) {match.group(2)}-{match.group(3)}'
    match = re.fullmatch(r'\(\d{3}\) \d{3} \d{4}', s)
    if match:
        return f'{match.group(1)}-{match.group(2)}-{match.group(3)}'
    match = re.fullmatch(r'\d{10}', s)
    if match:
        return f'({match.group(1)[:3]}) {match.group(1)[3:6]}-{match.group(1)[6:]}'
    return s

